SET @db := DATABASE();
SET @sql := IF(EXISTS(SELECT 1 FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=@db AND TABLE_NAME='websites' AND COLUMN_NAME='security_score'),'SELECT 1','ALTER TABLE websites ADD security_score TINYINT UNSIGNED NULL AFTER security_checked_at'); PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;
